/* prog51_union_find.c
 *
 * Re‑implementation of the original binary (prog51_union_find).
 * The program implements a tiny Union‑Find (Disjoint‑Set) structure
 * for ten elements (0 … 9) and processes commands supplied on the
 * command line.
 *
 * Supported commands (single‑letter tokens):
 *
 *   U a b   – union the sets containing a and b
 *   F a     – find the representative of a
 *   C a b   – test whether a and b are in the same set
 *
 * For each command the program prints a line exactly like the
 * original binary:
 *
 *   UNION a b
 *   FIND a=rep
 *   YES   or   NO
 *
 * If a command does not have enough arguments the program prints
 * "NOOP" and terminates.  If any numeric argument is out of the
 * allowed range (0‑9) the program prints "INVALID" and continues
 * with the next command.  Unrecognised command tokens also cause
 * "INVALID".
 *
 * The implementation follows the same logic as the de‑compiled
 * pseudo‑code, but is written in clear, idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define N 10                     /* fixed number of elements */

static int parent[N];
static int rankv[N];

/* Find with path compression */
static int find_set(int x)
{
    if (parent[x] != x)
        parent[x] = find_set(parent[x]);
    return parent[x];
}

/* Union by rank */
static void union_set(int x, int y)
{
    int rx = find_set(x);
    int ry = find_set(y);
    if (rx == ry)
        return;

    if (rankv[rx] < rankv[ry]) {
        parent[rx] = ry;
    } else if (rankv[rx] > rankv[ry]) {
        parent[ry] = rx;
    } else {
        parent[ry] = rx;
        rankv[rx]++;               /* increase rank of new root */
    }
}

/* Helper: check that a value is a valid element index */
static int valid_index(long v)
{
    return (v >= 0 && v < N);
}

int main(int argc, char *argv[])
{
    /* initialise the disjoint‑set structure */
    for (int i = 0; i < N; ++i) {
        parent[i] = i;
        rankv[i] = 0;
    }

    /* process command‑line tokens starting after the program name */
    int i = 1;                     /* current token index */
    while (i < argc) {
        const char *cmd = argv[i];

        if (strcmp(cmd, "U") == 0) {                     /* UNION */
            if (i + 2 >= argc) {                         /* not enough args */
                puts("NOOP");
                return 0;
            }
            long a = strtol(argv[i + 1], NULL, 10);
            long b = strtol(argv[i + 2], NULL, 10);
            if (!valid_index(a) || !valid_index(b)) {
                puts("INVALID");
                i += 3;
                continue;
            }
            union_set((int)a, (int)b);
            printf("UNION %ld %ld\n", a, b);
            i += 3;
        }
        else if (strcmp(cmd, "F") == 0) {                /* FIND */
            if (i + 1 >= argc) {
                puts("NOOP");
                return 0;
            }
            long a = strtol(argv[i + 1], NULL, 10);
            if (!valid_index(a)) {
                puts("INVALID");
                i += 2;
                continue;
            }
            int rep = find_set((int)a);
            printf("FIND %ld=%d\n", a, rep);
            i += 2;
        }
        else if (strcmp(cmd, "C") == 0) {                /* CONNECTED? */
            if (i + 2 >= argc) {
                puts("NOOP");
                return 0;
            }
            long a = strtol(argv[i + 1], NULL, 10);
            long b = strtol(argv[i + 2], NULL, 10);
            if (!valid_index(a) || !valid_index(b)) {
                puts("INVALID");
                i += 3;
                continue;
            }
            int ra = find_set((int)a);
            int rb = find_set((int)b);
            puts(ra == rb ? "YES" : "NO");
            i += 3;
        }
        else {                                           /* unknown token */
            puts("INVALID");
            ++i;
        }
    }

    return 0;
}
